// ARR - Credential liveness: one result per probe node. Edit PROBES to match your probe nodes.
const PROBES = ['Probe 1', 'Probe 2'];
const OK = code => code >= 200 && code < 300;

const problems = [];
for (const name of PROBES) {
  let item;
  try { item = $(name).first(); } catch (e) { problems.push(`${name} did not run`); continue; }
  const j = (item && item.json) || {};
  const code = Number(j.statusCode || (j.error && j.error.httpCode) || 0);
  if (OK(code)) continue;
  if (code === 401 || code === 403) problems.push(`${name} credential rejected (HTTP ${code})`);
  else if (code) problems.push(`${name} probe failed (HTTP ${code})`);
  else problems.push(`${name} got no response (${String((j.error && j.error.message) || 'network error or timeout').replace(/:/g, ' -')})`);
}
if (problems.length) {
  throw new Error(`ARR - Credential liveness failed, ${problems.length} of ${PROBES.length} credentials. ${problems.join('; ')}`);
}
return [{ json: { ok: true, checked: PROBES.length, at: new Date().toISOString() } }];
